package com.itools.app.tools

/** HTTP status codes: code, name, description (EN), description (ES). */
object HttpStatus {
    data class Code(val code: Int, val name: String, val en: String, val es: String)
    val categories = listOf(
        "1xx informational response" to "1xx respuesta informativa",
        "2xx success" to "2xx éxito",
        "3xx redirection" to "3xx redirección",
        "4xx client errors" to "4xx errores del cliente",
        "5xx server errors" to "5xx errores del servidor",
    )
    val codes = listOf(
        Code(100, "Continue", "Waiting for the client to emit the body of the request.", "Esperando a que el cliente envíe el cuerpo de la petición."),
        Code(101, "Switching Protocols", "The server has agreed to change protocol.", "El servidor acepta cambiar de protocolo."),
        Code(102, "Processing", "The server is processing the request, but no response is available yet (WebDAV).", "El servidor está procesando la petición pero aún no hay respuesta (WebDAV)."),
        Code(103, "Early Hints", "The server returns some response headers before final HTTP message.", "El servidor devuelve algunas cabeceras antes del mensaje final."),
        Code(200, "OK", "Standard response for successful HTTP requests.", "Respuesta estándar para peticiones correctas."),
        Code(201, "Created", "The request has been fulfilled, resulting in the creation of a new resource.", "La petición se completó y se creó un nuevo recurso."),
        Code(202, "Accepted", "The request has been accepted for processing, but the processing has not been completed.", "La petición se aceptó pero su procesamiento no ha terminado."),
        Code(203, "Non-Authoritative Information", "The request is successful but the content of the original request has been modified by a transforming proxy.", "Petición correcta, pero un proxy ha modificado el contenido."),
        Code(204, "No Content", "The server successfully processed the request and is not returning any content.", "El servidor procesó la petición y no devuelve contenido."),
        Code(205, "Reset Content", "The server indicates to reinitialize the document view which sent this request.", "El servidor indica que se reinicie la vista del documento."),
        Code(206, "Partial Content", "The server is delivering only part of the resource due to a range header sent by the client.", "Se entrega solo parte del recurso por una cabecera Range."),
        Code(207, "Multi-Status", "The message body that follows is an XML message and can contain a number of separate response codes (WebDAV).", "El cuerpo es XML y puede contener varios códigos de respuesta (WebDAV)."),
        Code(208, "Already Reported", "The members of a DAV binding have already been enumerated in a previous reply (WebDAV).", "Los miembros ya se enumeraron en una respuesta anterior (WebDAV)."),
        Code(226, "IM Used", "The server has fulfilled a request for the resource, and the response is a representation of the result of one or more instance-manipulations.", "La respuesta es el resultado de una o más manipulaciones de instancia."),
        Code(300, "Multiple Choices", "Indicates multiple options for the resource that the client may follow.", "Hay varias opciones para el recurso que el cliente puede seguir."),
        Code(301, "Moved Permanently", "This and all future requests should be directed to the given URI.", "Esta y futuras peticiones deben dirigirse a la URI indicada."),
        Code(302, "Found", "Redirect to another URL. The HTTP method may change.", "Redirección a otra URL; el método HTTP puede cambiar."),
        Code(303, "See Other", "The response to the request can be found under another URI using a GET method.", "La respuesta está en otra URI usando GET."),
        Code(304, "Not Modified", "Indicates that the resource has not been modified since the version specified by the request headers.", "El recurso no ha cambiado desde la versión indicada en las cabeceras."),
        Code(305, "Use Proxy", "The requested resource is available only through a proxy, the address for which is provided in the response.", "El recurso solo está disponible a través de un proxy."),
        Code(306, "Switch Proxy", "No longer used. Originally meant \"Subsequent requests should use the specified proxy.\"", "Ya no se usa. Indicaba que se usara el proxy especificado."),
        Code(307, "Temporary Redirect", "The request should be repeated with another URI; however, future requests should still use the original URI.", "Repetir la petición en otra URI; futuras peticiones usan la original."),
        Code(308, "Permanent Redirect", "The request and all future requests should be repeated using another URI.", "Esta y futuras peticiones deben repetirse en otra URI."),
        Code(400, "Bad Request", "The server cannot or will not process the request due to an apparent client error.", "El servidor no procesará la petición por un error del cliente."),
        Code(401, "Unauthorized", "Similar to 403 Forbidden, but specifically for use when authentication is required and has failed or has not yet been provided.", "Se requiere autenticación y ha fallado o no se ha proporcionado."),
        Code(402, "Payment Required", "Reserved for future use. The original intention was that this code might be used as part of some form of digital cash or micropayment scheme.", "Reservado para uso futuro (pagos digitales)."),
        Code(403, "Forbidden", "The request was valid, but the server is refusing action.", "Petición válida, pero el servidor rechaza la acción."),
        Code(404, "Not Found", "The requested resource could not be found but may be available in the future.", "El recurso no se encontró, aunque podría estar disponible en el futuro."),
        Code(405, "Method Not Allowed", "A request method is not supported for the requested resource.", "El método no está permitido para el recurso."),
        Code(406, "Not Acceptable", "The requested resource is capable of generating only content not acceptable according to the Accept headers sent in the request.", "El recurso solo genera contenido no aceptable según las cabeceras Accept."),
        Code(407, "Proxy Authentication Required", "The client must first authenticate itself with the proxy.", "El cliente debe autenticarse primero con el proxy."),
        Code(408, "Request Timeout", "The server timed out waiting for the request.", "Se agotó el tiempo esperando la petición."),
        Code(409, "Conflict", "Indicates that the request could not be processed because of conflict in the request.", "La petición no pudo procesarse por un conflicto."),
        Code(410, "Gone", "Indicates that the resource requested is no longer available and will not be available again.", "El recurso ya no está disponible y no volverá a estarlo."),
        Code(411, "Length Required", "The request did not specify the length of its content, which is required by the requested resource.", "La petición no indicó la longitud del contenido requerida."),
        Code(412, "Precondition Failed", "The server does not meet one of the preconditions that the requester put on the request.", "El servidor no cumple una de las precondiciones de la petición."),
        Code(413, "Payload Too Large", "The request is larger than the server is willing or able to process.", "La petición es mayor de lo que el servidor puede procesar."),
        Code(414, "URI Too Long", "The URI provided was too long for the server to process.", "La URI es demasiado larga para el servidor."),
        Code(415, "Unsupported Media Type", "The request entity has a media type which the server or resource does not support.", "El tipo de contenido no está soportado."),
        Code(416, "Range Not Satisfiable", "The client has asked for a portion of the file, but the server cannot supply that portion.", "El servidor no puede entregar la parte del archivo solicitada."),
        Code(417, "Expectation Failed", "The server cannot meet the requirements of the Expect request-header field.", "El servidor no puede cumplir la cabecera Expect."),
        Code(418, "I'm a teapot", "The server refuses the attempt to brew coffee with a teapot.", "El servidor se niega a hacer café con una tetera."),
        Code(421, "Misdirected Request", "The request was directed at a server that is not able to produce a response.", "La petición se dirigió a un servidor que no puede responder."),
        Code(422, "Unprocessable Entity", "The request was well-formed but was unable to be followed due to semantic errors.", "La petición es correcta pero tiene errores semánticos."),
        Code(423, "Locked", "The resource that is being accessed is locked (WebDAV).", "El recurso está bloqueado (WebDAV)."),
        Code(424, "Failed Dependency", "The request failed due to failure of a previous request (WebDAV).", "Falló por el fallo de una petición anterior (WebDAV)."),
        Code(425, "Too Early", "Indicates that the server is unwilling to risk processing a request that might be replayed.", "El servidor no arriesga procesar una petición que podría repetirse."),
        Code(426, "Upgrade Required", "The client should switch to a different protocol such as TLS/1.0.", "El cliente debe cambiar a otro protocolo, p. ej. TLS."),
        Code(428, "Precondition Required", "The origin server requires the request to be conditional.", "El servidor exige que la petición sea condicional."),
        Code(429, "Too Many Requests", "The user has sent too many requests in a given amount of time.", "Se han enviado demasiadas peticiones en poco tiempo."),
        Code(431, "Request Header Fields Too Large", "The server is unwilling to process the request because either an individual header field, or all the header fields collectively, are too large.", "Las cabeceras de la petición son demasiado grandes."),
        Code(451, "Unavailable For Legal Reasons", "A server operator has received a legal demand to deny access to a resource.", "Acceso denegado por motivos legales."),
        Code(500, "Internal Server Error", "A generic error message, given when an unexpected condition was encountered and no more specific message is suitable.", "Error genérico ante una condición inesperada."),
        Code(501, "Not Implemented", "The server either does not recognize the request method, or it lacks the ability to fulfill the request.", "El servidor no reconoce el método o no puede atender la petición."),
        Code(502, "Bad Gateway", "The server was acting as a gateway or proxy and received an invalid response from the upstream server.", "Actuando como pasarela o proxy, recibió una respuesta no válida."),
        Code(503, "Service Unavailable", "The server is currently unavailable (because it is overloaded or down for maintenance).", "El servidor no está disponible (sobrecarga o mantenimiento)."),
        Code(504, "Gateway Timeout", "The server was acting as a gateway or proxy and did not receive a timely response from the upstream server.", "Actuando como pasarela o proxy, no recibió respuesta a tiempo."),
        Code(505, "HTTP Version Not Supported", "The server does not support the HTTP protocol version used in the request.", "El servidor no soporta la versión de HTTP usada."),
        Code(506, "Variant Also Negotiates", "Transparent content negotiation for the request results in a circular reference.", "La negociación de contenido produce una referencia circular."),
        Code(507, "Insufficient Storage", "The server is unable to store the representation needed to complete the request (WebDAV).", "El servidor no puede almacenar lo necesario (WebDAV)."),
        Code(508, "Loop Detected", "The server detected an infinite loop while processing the request (WebDAV).", "Se detectó un bucle infinito (WebDAV)."),
        Code(510, "Not Extended", "Further extensions to the request are required for the server to fulfill it.", "Se requieren más extensiones para atender la petición."),
        Code(511, "Network Authentication Required", "The client needs to authenticate to gain network access.", "El cliente debe autenticarse para acceder a la red."),
    )
}
